def test_validation_before_enqueue():
    errors = []

    def enqueue(p):
        errors.append(p)
        return None

    try:
        api.submit("owner1", enqueue, batch_size=0)
    except ValueError:
        pass
    try:
        api.submit("owner1", enqueue, batch_size=101)
    except ValueError:
        pass
    try:
        api.submit("owner1", enqueue, batch_size=True)
    except ValueError:
        pass
    try:
        api.submit("owner1", enqueue, batch_size="20")
    except ValueError:
        pass
    assert errors == [], errors


def test_worker_uses_queued_batch_size():
